// Parity test: extract the <script id="core"> block from app.html, run it in node:vm,
// and compare against tests/vectors.json generated by the Python library.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import vm from "node:vm";

const here = dirname(fileURLToPath(import.meta.url));
const html = readFileSync(join(here, "app.html"), "utf8");
const m = html.match(/<script id="core">([\s\S]*?)<\/script>/);
if (!m) { console.error("core script block not found"); process.exit(1); }
const ctx = vm.createContext({});
vm.runInContext(m[1] + "\nthis.DupeCore = DupeCore;", ctx);
const C = ctx.DupeCore;
const V = JSON.parse(readFileSync(join(here, "..", "tests", "vectors.json"), "utf8"));
const REL = V.tolerance_rel, ABS = V.tolerance_abs;

let checks = 0, fails = 0;
function close(a, b, where) {
  checks++;
  if (typeof b === "string" || typeof b === "boolean") {
    if (a !== b) { fails++; console.error(`FAIL ${where}: ${a} !== ${b}`); }
    return;
  }
  if (Array.isArray(b)) {
    if (!Array.isArray(a) || a.length !== b.length) { fails++; console.error(`FAIL ${where}: length`); return; }
    b.forEach((x, i) => close(a[i], x, `${where}[${i}]`));
    return;
  }
  const d = Math.abs(a - b);
  if (!(d <= ABS || d <= REL * Math.max(Math.abs(a), Math.abs(b)))) {
    fails++; console.error(`FAIL ${where}: js=${a} py=${b} diff=${d}`);
  }
}

for (const c of V.cases) {
  const i = c.input;
  const r = C.analyze(i.players, i.field_size, i.prizes, { decay: i.decay, corr: i.corr });
  for (const [k, v] of Object.entries(c.output)) close(r[k], v, `${c.label}.${k}`);
}
for (const e of V.errors) {
  checks++;
  try {
    C.analyze(e.input.players, e.input.field_size);
    fails++; console.error(`FAIL expected error ${e.code}`);
  } catch (err) {
    if (err.code !== e.code) { fails++; console.error(`FAIL error code ${err.code} !== ${e.code}`); }
  }
}
const P = V.primitives;
P.base_probability.forEach((t, j) => close(C.baseProbability(t.in), t.out, `base_probability#${j}`));
P.salary_factor.forEach((t, j) => close(C.salaryFactor(...t.in), t.out, `salary_factor#${j}`));
P.binomial.forEach((t, j) => close(C.binomialPmfList(...t.in), t.out, `binomial#${j}`));
P.poisson.forEach((t, j) => close(C.poissonPmfList(...t.in), t.out, `poisson#${j}`));
P.tie_split.forEach((t, j) => close(C.tieSplit(...t.in), t.out, `tie_split#${j}`));
P.expected_first_payout.forEach((t, j) => close(C.expectedFirstPayout(t.in[0], t.in[1], t.in[2]), t.out, `expected_first_payout#${j}`));

// Parser smoke checks (no Python vectors; same rules as dfs_dupe.parsing).
const csv = 'Name,Position,Ownership,Salary,Team\nQB Alpha,QB,18%,"$6,400",AAA\n\nRB Bravo,RB,38,8600,BBB\n';
const pl = C.parsePlayersText(csv);
close(pl.length, 2, "parse.count"); close(pl[0].salary, 6400, "parse.salary"); close(pl[0].ownership, 18, "parse.own");
const tsv = C.parsePlayersText("salary\tname\town\tpos\n5000\tP1\t10\tQB");
close(tsv[0].name, "P1", "parse.tsv.name");
checks++;
try { C.parsePlayersText("A,QB,lots,5000"); fails++; console.error("FAIL bad number accepted"); } catch (e) { if (e.code !== "file") fails++; }

// Review fixes: formula-injection neutralizing in CSV export, BOM, size cap, non-array prizes.
close(C.csvCell("=CMD|' /C calc'!A0"), "'=CMD|' /C calc'!A0", "csv.formula.eq");
close(C.csvCell("+1"), "'+1", "csv.formula.plus");
close(C.csvCell("-1"), "'-1", "csv.formula.minus");
close(C.csvCell("@SUM(A1)"), "'@SUM(A1)", "csv.formula.at");
close(C.csvCell("\t=1"), "'\t=1", "csv.formula.tab");
close(C.csvCell('=A,"b"'), `"'=A,""b"""`, "csv.formula.quoted");
close(C.csvCell(-0.5), "-0.5", "csv.number.negative");
close(C.csvCell("QB Alpha"), "QB Alpha", "csv.plain");
close(C.parsePlayersText("\ufeffname,position,ownership,salary\nA,QB,10,5000")[0].name, "A", "parse.bom");
for (const [label, f] of [
  ["size.text", () => C.parsePlayersText("a".repeat(C.MAX_BYTES + 1))],
  ["size.json", () => C.parseJsonText(" ".repeat(C.MAX_BYTES + 1))],
  ["prizes.number", () => C.analyze(C.EXAMPLES.chalk, 100, 5)],
]) {
  checks++;
  try { f(); fails++; console.error(`FAIL ${label} accepted`); } catch (e) { if (!e.code) { fails++; console.error(`FAIL ${label}: ${e}`); } }
}

if (fails) { console.error(`${fails} of ${checks} checks failed`); process.exit(1); }
console.log(`parity ok: ${checks} checks across ${V.cases.length} cases, ${V.errors.length} error cases`);
